#!/usr/bin/env python3
"""Resumo visual DA — leva 1 (itens 1, 2 e 3 do edital): P1-DA-1, 1.1, 1.2, 2.1, 2.2, 3.1, 3.2, 3.3, 3.4.
Produção Cowork (Fable), 28/10/2026, ESPEC_resumo_visual_DA_v3. Base de conteúdo: pacote v1.14 (resumo, emUmMinuto, baseLegal já
conferidos) e texto das normas; blocos dos resumos MapasPro só após a triagem (TRIAGEM_resumos_MapasPro_DA_2026-10-28.md).
Gera resumo_visual_leva1.json. Os blocos `lei` reaproveitam os dispositivos `baseLegal` do pacote (com `conferido`)."""
import json
EX = json.load(open('/home/claude/v17_3/extras_leva1_v114.json', encoding='utf-8'))
FONTE_COB = "Corpus Cebraspe 2025 (fila v2, enquadramento do pacote de auditoria, a confirmar no CDN)."
def limpa(o):
    """ajustes ao herdar do pacote (QA R1 D28 e D33): rótulo de probabilidade sem fonte vira 'típica'; anotação editorial do
    Planalto sai do texto literal do art. 21 da Lei 8.112 (o pacote v1.14 recebe despacho para corrigir na origem)."""
    if isinstance(o, dict): return {k: limpa(v) for k, v in o.items()}
    if isinstance(o, list): return [limpa(v) for v in o]
    if isinstance(o, str): return o.replace("Pegadinha provável", "Pegadinha típica").replace(" (prazo 3 anos - vide EMC nº 19)", "").replace("(prazo 3 anos - vide EMC nº 19)", "")
    return o
def lei(tid, k=0, titulo=None):
    """bloco lei = baseLegal já conferido do pacote (índice k entre os baseLegal do tópico)"""
    bls = [v for v in EX[tid]["visuais"] if v["tipo"] == "baseLegal"]
    v = bls[k]; return limpa({"t": "lei", "titulo": titulo or v.get("titulo"), "norma": v.get("norma"), "dispositivos": v["dispositivos"]})
def compare(tid, k=0):
    cs = [v for v in EX[tid]["visuais"] if v["tipo"] == "compare"]; v = dict(cs[k]); v["t"] = "compare"; v.pop("tipo"); return limpa(v)
def tabela_pacote(tid, k=0):
    ts = [v for v in EX[tid]["visuais"] if v["tipo"] == "tabela"]; v = dict(ts[k]); v["t"] = "tabela"; v.pop("tipo"); return limpa(v)
def esquema_pacote(tid, k=0):
    es = [v for v in EX[tid]["visuais"] if v["tipo"] == "esquema"]; v = dict(es[k]); v["t"] = "esquema"; v.pop("tipo"); return limpa(v)
S = lambda t, i="pino": {"t": "secao", "titulo": t, "icone": i}
U = lambda t, i=None: {"t": "sub", "titulo": t, **({"icone": i} if i else {})}
T = lambda md: {"t": "texto", "md": md}
B = lambda tipo, rotulo, md: {"t": "box", "tipo": tipo, "rotulo": rotulo, "md": md}
TB = lambda titulo, cols, rows, leg=None: {"t": "tabela", "titulo": titulo, "colunas": cols, "linhas": rows, **({"legenda": leg} if leg else {})}
DOIS = lambda titulo, a, ai, b, bi, pe=None, leg=None: {"t": "dois", "titulo": titulo, "a": {"titulo": a, "itens": ai}, "b": {"titulo": b, "itens": bi}, **({"pe": pe} if pe else {}), **({"legenda": leg} if leg else {})}
MAPA = lambda titulo, centro, ramos, leg=None: {"t": "mapa", "titulo": titulo, "centro": centro, "ramos": [{"titulo": r[0], "texto": r[1]} for r in ramos], **({"legenda": leg} if leg else {})}
REL = lambda itens: {"t": "relampago", "itens": itens}
PEG = lambda pares: {"t": "pegadinhas", "itens": [{"errado": e, "certo": c} for e, c in pares]}
R = {}

